    @auto
    class MyClass:
        def __init__(self, a, b=AlwaysEqual(1)):
            self.a = a
            self.b = b

    # Create instance where b is not the default object, but compares equal
    obj2 = MyClass(1, b=AlwaysEqual(2))
    # The @auto decorator adds __repr__ and __rich_repr__
    # __repr__ calls __rich_repr__, which uses auto_rich_repr

    repr_str = repr(obj2)
    # Expected output if 'is' is used: MyClass(a=1, b=AlwaysEqual(2))
    # Expected output if '==' is used: MyClass(a=1) because AlwaysEqual(2) == AlwaysEqual(1) is True

    assert "b=AlwaysEqual(2)" in repr_str
    assert "a=1" in repr_str

if __name__ == "__main__":
    try:
        test_repr_custom_class()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
    except Exception as e:
        print(f"Error: {e}")
