from rich.repr import auto

class AlwaysEqual:
    def __init__(self, value):
        self.value = value
    def __eq__(self, other):
        return True
    def __repr__(self):
        return f"AlwaysEqual({self.value!r})"

@auto
class MyClass:
    def __init__(self, a, b=AlwaysEqual(1)):
        self.a = a
        self.b = b

def test_repr_custom_class():
    # Case 1: Value is different but compares equal
    obj2 = MyClass(1, b=AlwaysEqual(2))
    repr_str = repr(obj2)
    print(f"Repr 2: {repr_str}")
    assert "b=AlwaysEqual(2)" in repr_str

    # Case 2: Value is the same object as default
    # Need to get the default value from the signature
    import inspect
    sig = inspect.signature(MyClass.__init__)
    default_b = sig.parameters['b'].default
    obj1 = MyClass(1, b=default_b)
    repr_str1 = repr(obj1)
    print(f"Repr 1: repr(obj1) = {repr_str1}")
    # Should be omitted if it's the same object
    assert "b=" not in repr_str1

if __name__ == "__main__":
    try:
        test_repr_custom_class()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
    except Exception as e:
        import traceback
        traceback.print_exc()
        exit(1)
